class stringx {
public:
    stringx();
    stringx(const stringx&);
    ~stringx();
};

stringx operator+(const char*, const stringx&);
stringx operator+(const stringx&, const char*);

class vm_thread {
public:
    void slf_error(const stringx&);
};

class vm_stack {
    char unused[8];
    char* sp;
    vm_thread* thread;
public:
    void pop(int bytes) { sp -= bytes; }
    char* get_SP() const { return sp; }
    vm_thread* get_thread() const { return thread; }
};

class region {
    char unused[0x118];
    unsigned short flags;
public:
    void set_active(bool);
    void set_locked(bool v) { flags = v ? (flags | 2) : (flags & ~2); }
};

class region_node {
    char unused[4];
    region* data;
public:
    region* get_data() { return data; }
};

class terrain {
public:
    region_node* find_region(const stringx&);
};

class world_dynamics_system {
    char unused[0xec];
    terrain* the_terrain;
public:
    terrain& get_the_terrain() { return *the_terrain; }
};

extern world_dynamics_system* g_world_ptr;

class script_library_class {
public:
    class function {
    public:
        enum entry_t { FIRST_ENTRY };
    };
};

typedef const stringx* vm_str_t;
typedef float vm_num_t;

class slf_set_region_active_t : public script_library_class::function {
public:
    struct parms_t {
        vm_str_t region_name;
        vm_num_t v;
    };

    virtual bool operator()(vm_stack& stack, entry_t entry)
    {
        stack.pop(sizeof(parms_t));
        parms_t* parms = (parms_t*)stack.get_SP();
        region_node* rn = g_world_ptr->get_the_terrain().find_region(*parms->region_name);
        if (!rn)
        {
            stack.get_thread()->slf_error("set_region_active(): region '" + *parms->region_name + "' not found");
        }
        region* r = rn->get_data();
        r->set_locked(false);
        if (parms->v)
            r->set_active(true);
        else
        {
            r->set_active(false);
            r->set_locked(true);
        }
        return true;
    }
};
